// ---------------------------------------------------------------------------------------------------------------------------
// hkv_kowloon kit: curtain-wall towers on real rings, mullions / fins along the perimeter, spandrel bands, setback tiers,
// roof-edge light lines, and an additive LED layer (abstract colour fields only) for the TST East / Hung Hom LED walls.
// Every ring is the real OSM footprint in local metres around the key's anchor (+x east, +z south); rot is always 0.
// ---------------------------------------------------------------------------------------------------------------------------
const KP = k => ({lat:D[k].ll[0], lon:D[k].ll[1]});
const place = k => SG_PLACES.push({type:k, lat:D[k].ll[0], lon:D[k].ll[1], rot:0});
const RG = (k, n) => D[k][n].r;
const glassS = (c, lc, o) => Object.assign({c, m:1, lc:lc || '#ffe0b0', lk:0.5, fh:3.6, cw:2.6}, o || {});
// vertical members at an even spacing along the perimeter (works on curved rings): flat strips (dep 0) or boxes `dep` deep
