  if (S.shop !== false){ const Q = offP(P, -0.06); prismP(B.p(S.sc || {c:'#3c4248', glow:'#ffd9a0', gk:0.45}), Q, 0.3, Math.min(y1 - 0.5, S.sh || 4.6), true); }
