// =====================================================================================================================
// Harbour City (Wharf, 1980s-90s): The Gateway towers 1, 2, 5, 6 and the Prudential Tower (OSM 129 m, 35-36 levels from the podium
// at 12 m) in teal-blue reflective glass with rounded corners, T6 greener; the 16-storey hotel / office blocks on the Canton Road side
// (Prince, Gateway, North / South, World Commerce Centre, Wharf T&T Centre; OSM 55 m, saw-tooth bay windows on their west faces);
// the Gateway Arcade podium (r19760571, 12 m); and the pink granite "Gateway" arch block on the water side (w152073881).
// Night: lit floors, the thin white-pink light lines along every roof edge (photos 0001, 0022), the arch outlined in pink.
// =====================================================================================================================
LANDMARKS.hkvharbourcity = {zh:'海港城', en:'Harbour City', cat:'new', r:253, h:133,
  lt:{m:0, c:'#ffe0c0', k:0.3},
  build(){
    const k = 'hkvharbourcity', g = new THREE.Group(), B = mkB(), G = mkG(KP(k).lat, KP(k).lon), A = RG(k, 'arc');
    skirt(B, G, A);
    POD(B, A, 0, 12, {c:'#cfc5b4', band:'#a8a08f', fh:6, bh:0.9, canopy:'#8d8676'});
    const TEAL = glassS('#3d6a78', '#e8f0ff', {lk:0.45, fh:3.6, cw:2.8}), GRN = glassS('#3f7468', '#e8f6f0', {lk:0.45, fh:3.6, cw:2.8});
    const EDGE = '#ffd6e4';
    for (const [n, gl] of [['t1', TEAL], ['t2', TEAL], ['t5', TEAL], ['pru', TEAL], ['t6', GRN]]){
      const P = RG(k, n);
      TW(B, P, 12, 129, {gl, bh:0.35, bc:'#2f4a52', fh:3.35, ms:1.5, mw:0.12, mc:'#6f8f99', ph:1.6, pc:'#5d7880', rc:'#7a7f80', plant:7, plh:3.5, edge:EDGE, ek:1.4});
      bandsP(B.p('#e6ecee'), P, 12, 14.5, 2.0, 0.6, 0.1); }
    // the hotel / office blocks on Canton Road: dark blue-grey glass, aluminium bands; N and S step back at 43 m
    const HB = glassS('#46535d', '#ffdcae', {fh:3.1, cw:2.4}), HO = glassS('#4b5a63', '#e8f0ff', {fh:3.4, cw:2.8});
    for (const [n, gl, top] of [['prince', HB, 55], ['gw', HB, 55], ['wcc', HO, 55], ['wtt', HO, 55], ['n', HO, 43], ['s', HO, 43]]){
      const P = RG(k, n);
      TW(B, P, 12, top, {gl, bh:0.6, bc:'#a9b0b4', fh:gl === HB ? 3.1 : 3.4, ms:3.0, mw:0.3, mc:'#9aa2a6', ph:1.2, rc:'#7c7f80', plant: top === 55 ? 8 : 0, edge:EDGE, ek:1.1});
      if (top === 43){ const Q = offP(P, 3.5); TW(B, Q, 43, 55, {gl, bh:0.6, bc:'#a9b0b4', fh:3.4, ms:3.0, mw:0.3, mc:'#9aa2a6', ph:1.2, edge:EDGE, ek:1.1}); } }
    // the Gateway arch: pink granite legs and lintel, the square opening facing the harbour
    { const P = RG(k, 'arch'), ax = axisP(P), aA = axisP(A); ax[2] = aA[2]; ax[3] = aA[3];   // legs at the N and S ends (along Canton Road), the opening faces the harbour
      { let a = 0, b = 0; for (const p of P){ const x = p[0]-ax[0], z = p[1]-ax[1]; a = Math.max(a, Math.abs(x*ax[2] + z*ax[3])); b = Math.max(b, Math.abs(-x*ax[3] + z*ax[2])); } ax[4] = a; ax[5] = b; }
      const L = ax[4], PINK = {c:'#c79a8c', lc:'#ffc8c8', lk:0.5};
      for (const [s0, s1] of [[-L - 1, -L + 9], [L - 9, L + 1]]){ const Q = sliceP(P, ax, s0, s1); if (Q.length > 2) prismP(B.p(PINK), Q, 12, 44, false); }
      prismP(B.p(PINK), P, 44, 55, false);
      winsP(B.p({c:'#3a3f44', glow:'#ffd2a8', gk:0.4}), offP(P, -0.06), 45.5, 54, 3.1, 2.2, 1.4, 1.9, 0, null);
      const ln = B.p({c:'#e8c0c0', glow:'#ff5a9a', gk:1.6}), u = [ax[2], ax[3]], v = [-ax[3], ax[2]], w = ax[5] + 0.3;
      for (const sv of [-1, 1]){ const pt = (s, y) => [ax[0] + u[0]*s + v[0]*sv*w, y, ax[1] + u[1]*s + v[1]*sv*w];
        segP(ln, pt(-L + 9, 12.5), pt(-L + 9, 44), 0.22, 3); segP(ln, pt(L - 9, 12.5), pt(L - 9, 44), 0.22, 3); segP(ln, pt(-L + 9, 44), pt(L - 9, 44), 0.22, 3);
        segP(ln, pt(-L, 55), pt(L, 55), 0.22, 3); } }
    B.flush(g); return g; }};
place('hkvharbourcity');

