// =====================================================================================================================
LANDMARKS.hkvonepeking = {zh:'北京道一号', en:'One Peking', cat:'new', r:32, h:160,
  lt:{m:0, c:'#dfeaff', k:0.4},
  build(){
    const k = 'hkvonepeking', g = new THREE.Group(), B = mkB(), G = mkG(KP(k).lat, KP(k).lon), P = RG(k, 'r'), ax = axisP(P);
    skirt(B, G, P);
    POD(B, P, 0, 12, {c:'#9aa3a6', band:'#7d8689', fh:6, bh:0.6});
    TW(B, P, 12, 132, {gl:glassS('#4f7680', '#e8f2ff', {fh:4.0, cw:3.0}), bh:0.3, bc:'#365058', fh:4.0, ms:1.6, mw:0.14, mc:'#8fb0b8', ph:0});
    // the sail: roof line rising along the long axis from 132 m to 160 m at the south-west (harbour) end
    const s0 = -ax[4], s1 = ax[4], yS = (x, z) => { const s = (x - ax[0])*ax[2] + (z - ax[1])*ax[3], t = cl01((s - s0)/(s1 - s0)); const e = ax[2] < 0 ? t : 1 - t; return 132 + 28*Math.pow(e, 1.6); };
    prismP(B.p({c:'#7fa3ae', lc:'#e8f2ff', lk:0.9, op:0.75}), P, 132, yS, false);
    mullR(B.p({c:'#c8d2d6', glow:'#dff0ff', gk:0.7}), P, 132, 133, 3.0, 0.3, 0.3, 0.05);
    { const o = B.p({c:'#d8e2e6', glow:'#e6f4ff', gk:1.1}); for (let i = 0; i < P.length; i++){ const a = P[i], b = P[(i+1) % P.length]; segP(o, [a[0], yS(a[0], a[1]), a[1]], [b[0], yS(b[0], b[1]), b[1]], 0.25, 3); } }
    B.flush(g); return g; }};
place('hkvonepeking');

