LANDMARKS.hkvtstc = {zh:'尖沙咀中心', en:'Tsim Sha Tsui Centre', cat:'new', r:60, h:47,
  lt:{m:0, c:'#e6f0ff', k:0.3, anim:'cycle', c2:'#7fc8ff'},
  build(){
    const k = 'hkvtstc', g = new THREE.Group(), B = mkB(), G = mkG(KP(k).lat, KP(k).lon), P = RG(k, 'r');
    skirt(B, G, P); POD(B, P, 0, 9, {c:'#4a4d50', band:'#8a8e90', fh:4.5, bh:0.5});
    TW(B, P, 9, 44.4, {gl:glassS('#2c353d', '#e8f0ff', {fh:3.1, cw:2.8}), bh:0.25, bc:'#55616a', fh:3.1, ms:1.6, mw:0.1, mc:'#5d6a74', ph:1.2, plant:9});
    // the LED wall: a 26 m wide screen in the middle of the harbour face (scout: about 24 x 34 m), not the whole face
    { const pos = [], pick = faceOf(P, 155, 35); let best = -1, L = 0; for (let i = 0; i < P.length; i++) if (pick(i)){ const a = P[i], b = P[(i+1) % P.length], l = Math.hypot(b[0]-a[0], b[1]-a[1]); if (l > L){ L = l; best = i; } }
      if (best >= 0){ const a = P[best], b = P[(best+1) % P.length], [nx, nz] = outN(P, best), ux = (b[0]-a[0])/L, uz = (b[1]-a[1])/L, m = [(a[0]+b[0])/2 + nx*0.3, (a[1]+b[1])/2 + nz*0.3], w = Math.min(13, L/2 - 1);
        quadP(pos, [m[0] - ux*w, 9.5, m[1] - uz*w], [m[0] + ux*w, 9.5, m[1] + uz*w], [m[0] + ux*w, 43.5, m[1] + uz*w], [m[0] - ux*w, 43.5, m[1] - uz*w]); }
      hkvLED(g, pos, 0, 1.0, 0.2); }
    B.flush(g); return g; }};
place('hkvtstc');
