// harbour face (photo 0030). Harbour Grand Kowloon (OSM 62 m, glass), One and Two Harbourfront (OSM 110 m, glass offices),
// Kerry Hotel (2017, OSM 70 m and parts: curved dark glass), Harbour Plaza Metropolis (OSM 22 levels from the podium at 21.7 m:
// pinkish-beige slab with saw-tooth bays), Metropolis Tower (offices) and The Metropolis Residence (31 levels).
// =====================================================================================================================
LANDMARKS.hkvhflandmark = {zh:'海名轩', en:'The Harbourfront Landmark', cat:'new', r:56, h:233,
  lt:{m:0, c:'#e6f0ff', k:0.35},
  build(){
    const k = 'hkvhflandmark', g = new THREE.Group(), B = mkB(), G = mkG(KP(k).lat, KP(k).lon);
    const GL = glassS('#4d7684', '#ffe2b8', {fh:3.1, cw:2.2});
    const pos = [];
    for (const [n, h] of [['t1', 223], ['t2', 215], ['t3', 207]]){ const P = RG(k, n); skirt(B, G, P);
      POD(B, offP(P, -1.5), 0, 12, {c:'#c0bdb4', band:'#98958c', fh:6, bh:0.6});
      TW(B, P, 12, h - 10, {gl:GL, bh:0.3, bc:'#2f4a54', fh:3.1, ms:2.2, mw:0.25, mc:'#cfd8dc', md:0.3, ph:0});
      const Q = offP(P, 2.0); TW(B, Q, h - 10, h, {gl:{c:'#7ea2ae', glow:'#e8f4ff', gk:0.5}, ms:2.0, mw:0.3, mc:'#e0e6e8', ph:2.5, pc:'#e0e6e8', edge:'#e8f4ff', ek:1.0});
      if (n === 't2'){ const ax = axisP(P), zS = bbP(P)[3]; LBox(g, 1.4, h - 20, 1.0, ax[0] + 3, 14, zS + 0.5, {c:'#eef2f4', glow:'#ffffff', gk:0.9});
        const x = ax[0] - 3, z = zS + 0.7; quadP(pos, [x - 2, 14, z], [x + 2, 14, z], [x + 2, h - 12, z], [x - 2, h - 12, z]); } }
    LCyl(g, 0.4, 0.8, 10, RG(k, 't1').reduce((s, p) => s + p[0], 0)/RG(k, 't1').length, 223, RG(k, 't1').reduce((s, p) => s + p[1], 0)/RG(k, 't1').length, '#a8a8a8', 6);
    hkvLED(g, pos, 1, 1.0, 0.3);
    B.flush(g); return g; }};
place('hkvhflandmark');
